from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import AnasensorURI


class AnasensorV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_sensor_data(self, node_id, timeout=60):
        uri = AnasensorURI().sensor_data_uri + "/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_server_cups_data(self, node_id, timeout=60):
        uri = AnasensorURI().cups_data_uri + "/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_notification_rules(self, timeout=60):
        uri = AnasensorURI().notification_rules_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def delete_notification_rule(self, rule_id, timeout=60):
        uri = AnasensorURI().notification_rules_uri + "/id/" + rule_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def add_notification_rule(self, rule_name, rule_type, timeout=60, **kwargs):
        uri = AnasensorURI().notification_rules_uri
        data = {
            "rule_name": rule_name,
            "rule_type": rule_type,
            **kwargs
        }
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def get_system_dn(self, timeout=60):
        uri = AnasensorURI().system_dn_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)['system_dn']

    def modify_system_dn(self, system_dn, timeout=60):
        uri = AnasensorURI().system_dn_uri
        data = {"system_dn": system_dn}
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def get_all_snmp_trap_destinations(self, timeout=60):
        uri = AnasensorURI().snmptrap_dest_uri
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_snmp_trap_destination_by_id(self, id, timeout=60):
        uri = AnasensorURI().snmptrap_dest_uri + '/id/' + id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)[0]

    def modify_snmp_trap_destination_by_id(self, id, timeout=60, **kwargs):
        uri = AnasensorURI().snmptrap_dest_uri + '/id/' + id
        return self.api_client.send_post_request(uri=uri, json=kwargs, timeout=timeout)

    def add_snmp_trap_destination(self, timeout=60, **kwargs):
        uri = AnasensorURI().snmptrap_dest_uri
        return self.api_client.send_post_request(uri=uri, json=kwargs, timeout=timeout)

    def delete_snmp_trap_destination_by_id(self, id, timeout=60):
        uri = AnasensorURI().snmptrap_dest_uri + '/id/' + id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

